xml.Script:
        clWhite1  := 'F0F0F0';
        clWhite2  := 'F0F0F1';
        clWhite3  := 'F0F1F0';
        clWhite4  := 'F1F0F0';

        clBlue1   := '0000FF';
        clBlue2   := '0100FF';
        clBlue3   := '0001FF';
        clBlue4   := '0101FF';

        clRed1    := 'FF0000';
        clRed2    := 'FF0100';
        clRed3    := 'FF0001';
        clRed4    := 'FF0101';

        clOrange1 := 'FF6000';
        clOrange2 := 'FF6001';
        clOrange3 := 'FF6100';
        clOrange4 := 'FF6101';

        clGreen1  := '008000';
        clGreen2  := '018000';
        clGreen3  := '008100';
        clGreen4  := '008001';

        Scale := 0.5;

        s5 := sqrt(5);
        C0 := Scale * sqrt(10 * (25 - 11 * s5)) / 20;
        C1 := Scale * sqrt(10 * ( 5 -      s5)) / 20;
        C2 := Scale * sqrt(10 * ( 5 +      s5)) / 20;
        C3 := Scale * sqrt(10 * ( 5 -      s5)) / 10;
        C4 := Scale * sqrt( 2 * ( 5 -      s5)) /  4;
        C5 := Scale * sqrt(10 * ( 5 +      s5)) / 10;
        C6 := Scale * sqrt( 2 * ( 5 +      s5)) /  4;
        C7 := Scale * sqrt(10 * (25 + 11 * s5)) / 20;
        C8 := Scale * sqrt( 5 * ( 5 +  2 * s5)) /  5;

        Ax := C4 * C6 - C2 * C4;
        Ay :=          -C5 * C6;
        Az :=           C5 * C4;

        Bx := C4 * C6 - C2 * C4;
        By :=           C5 * C6;
        Bz :=          -C5 * C4;

        Cx := C1 * C6 + C4 * C6;
        Cy :=          -C3 * C6;
        Cz :=           C3 * C4;

        Dx := C1 * C6 + C4 * C6;
        Dy :=           C3 * C6;
        Dz :=          -C3 * C4;
